<template><div class="card-body"><el-form label-position="top"><div class="form-grid"><el-form-item label="试卷名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="课程"><el-select v-model="form.course" style="width:100%"><el-option v-for="c in store.courses" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="考试时间"><el-input-number v-model="form.duration" :min="1"/> 分钟</el-form-item><el-form-item label="目标总分"><el-input-number v-model="form.target_score" :min="1"/></el-form-item></div></el-form><div class="split-layout"><div><div class="toolbar"><el-input v-model="keyword" placeholder="筛选已审核题目"/><el-button @click="loadQuestions">查询</el-button></div><el-table :data="questions" height="420"><el-table-column prop="stem" label="题目" show-overflow-tooltip/><el-table-column prop="question_type" label="题型" width="100"/><el-table-column prop="score" label="分值" width="60"/><el-table-column label="" width="70"><template #default="s"><el-button link type="primary" @click="add(s.row)">加入</el-button></template></el-table-column></el-table></div><div class="selected card card-body"><h3>已选题目（{{selected.length}}道，{{total}}分）</h3><div v-for="(q,i) in selected" :key="q.id" class="selected-item"><span>{{i+1}}. {{q.stem}}</span><el-input-number v-model="q.paperScore" :min=".5" :step=".5" size="small"/><el-button link type="danger" @click="selected.splice(i,1)">移除</el-button></div></div></div><el-button type="primary" :loading="saving" style="margin-top:18px" @click="submit">创建并进入编辑器</el-button></div></template><script setup>import{ref,reactive,computed,onMounted}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{questionsApi,papersApi}from'../../../api';import{useAppStore}from'../../../stores/app';const router=useRouter(),store=useAppStore(),questions=ref([]),selected=ref([]),keyword=ref(''),saving=ref(false),form=reactive({name:'',course:'',duration:90,target_score:100,paper_type:'手动组卷'}),total=computed(()=>selected.value.reduce((n,x)=>n+Number(x.paperScore),0));const loadQuestions=async()=>{if(!form.course)return;const d=await questionsApi.list({course:form.course,review_status:'APPROVED',keyword:keyword.value,page_size:100});questions.value=d.items};const add=q=>{if(selected.value.some(x=>x.id===q.id))return ElMessage.info('该题已加入');selected.value.push({...q,paperScore:Number(q.score)})};const submit=async()=>{if(!form.name||!form.course||!selected.value.length)return ElMessage.warning('请填写试卷信息并至少选择一道题');saving.value=true;try{const p=await papersApi.manual({...form,sections:[{title:'一、综合题',questions:selected.value.map(x=>({question_id:x.id,score:x.paperScore}))}]});router.push(`/papers/${p.id}/edit`)}finally{saving.value=false}};onMounted(async()=>{await store.loadCourses();form.course=store.courses[0]?.id||'';loadQuestions()})</script><style scoped>.selected{max-height:470px;overflow:auto}.selected-item{display:grid;grid-template-columns:1fr 110px 50px;gap:8px;align-items:center;padding:10px 0;border-bottom:1px solid var(--border)}.selected-item span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}</style>
